"""One-time installation of the reviewed Data Observatory profile assets.
Generated from the local design package. Creates only the listed README,
assets, docs and statistics script, then removes this installer.
"""
import base64
import json
import zlib
from pathlib import Path

DATA = ""
root = Path(__file__).resolve().parent
files = json.loads(zlib.decompress(base64.b64decode(DATA)))
for name, content in files.items():
    path = (root / name).resolve()
    if not path.is_relative_to(root) or name.split('/')[0] not in {'README.md', 'assets', 'docs', 'scripts'}:
        raise ValueError('Invalid prepared asset path')
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
(root / 'snake.yml').unlink(missing_ok=True)
Path(__file__).unlink()
print(f'Installed {len(files)} prepared profile files.')
